  PITON_DESC_APPEND(a);PITON_DESC_APPEND(method);PITON_DESC_APPEND(b);PITON_DESC_APPEND(owner);PITON_DESC_APPEND(c);PITON_DESC_APPEND(actual);PITON_DESC_APPEND(d);m[o]=0;
